  'late-chunking': { front: 'Late chunking', back: 'Embed full document first, then chunk the embedding. Chunks share document-level context that early-chunked embeddings lose.' },
  'vector-database': { front: 'Vector database', back: 'A database for ANN (approximate nearest-neighbor) search over vector embeddings. Pinecone, Qdrant, Weaviate, pgvector, etc.' },
  'pinecone': { front: 'Pinecone', back: 'A managed vector database. Pioneered the category around 2021; popular default for hosted production RAG.' },
  'weaviate': { front: 'Weaviate', back: 'Open-source vector database with built-in hybrid search and modular embedding generation. Self-hosted or managed.' },
  'qdrant': { front: 'Qdrant', back: 'Open-source Rust-native vector database. Fast, simple API, strong defaults. Popular 2026 self-hosted choice.' },
  'chroma': { front: 'Chroma', back: 'Embedded vector database designed for local development and small-to-medium production. SQLite-style ergonomics for AI builders.' },
  'lancedb': { front: 'LanceDB', back: 'Embedded columnar vector database backed by Lance (Parquet-derived format). Optimized for hybrid analytical and vector queries.' },
  'milvus': { front: 'Milvus', back: 'Purpose-built vector database for billion-scale workloads. Separates compute and storage; needs Kubernetes.' },
  'pgvector': { front: 'pgvector', back: 'A Postgres extension that adds a vector data type with HNSW and IVFFlat indexes. "Use the database you already have."' },
  'hnsw': { front: 'HNSW', back: 'Hierarchical Navigable Small World. Graph-based ANN algorithm; the dominant default for vector search. Best recall-latency tradeoff.' },
  'ann': { front: 'ANN', back: 'Approximate Nearest Neighbor search. Trades small recall loss (typically <2%) for 100-1000x speedup over exact search.' },
  'ivf': { front: 'IVF', back: 'Inverted File index. ANN algorithm that partitions vectors into clusters; searches only clusters closest to the query.' },
  'ivf-pq': { front: 'IVF-PQ', back: 'IVF combined with Product Quantization. Compresses each vector into a few bytes; enables billion-scale indexes in modest memory.' },
