  'hybrid-search': { front: 'Hybrid search', back: 'Combining vector (semantic) and lexical (BM25) retrieval. Catches both kinds of relevance: paraphrase and exact-match.' },
  'rrf': { front: 'RRF', back: 'Reciprocal Rank Fusion. Combines multiple ranked lists by summing 1/(k+rank). The standard fusion algorithm for hybrid search.' },
  'reranking': { front: 'Reranking', back: 'Second-stage retrieval that scores (query, doc) pairs more carefully (typically cross-encoder). Lifts precision after broad first-stage retrieval.' },
  'bm25': { front: 'BM25', back: 'Lexical retrieval algorithm. Pre-LLM IR baseline; still essential as the lexical leg of hybrid search. Strong on exact-match terms.' },
