  'opencode': { front: 'OpenCode', back: 'Open-source alternative to Claude Code. Community-driven; rapid iteration.' },
  'devin': { front: 'Devin', back: 'Cognition\'s autonomous SWE agent. "Background coding agent" archetype; you assign tasks, it returns PRs.' },
  'replit-agent': { front: 'Replit Agent', back: 'Replit\'s agent that builds entire apps from prompts. End-to-end deploy on Replit infrastructure.' },
  'openai-codex-the-agent-not-the-cli': { front: 'OpenAI Codex (agent)', back: 'OpenAI\'s autonomous coding agent service (distinct from the CLI). Background-agent pattern; operates on real repos.' },
