  'token-cost-for-coding-agents': { front: 'Coding agent token cost', back: 'Coding workloads are token-heavy. Expect $20-200/mo personal subscriptions; multiplies with autonomous background agents.' },
  'personal-subscription-tier-landscape': { front: 'Personal subscription tier landscape', back: 'Cursor Pro, Claude Pro / Max, GitHub Copilot Pro, Continue free + paid. Stacking 2-3 is common.' },

  // ===== Module 15: AI Product Design Patterns =====
  'manual': { front: 'Manual', back: 'Human does everything; AI not involved. Baseline against which AI features are measured.' },
  'suggest': { front: 'Suggest', back: 'AI proposes, human accepts or rejects. Copilot, Grammarly. Lowest autonomy on the ladder.' },
  'assist': { front: 'Assist', back: 'AI does the work, human supervises. Cursor agent mode. Mid-autonomy; human still owns each step.' },
  'automate': { front: 'Automate', back: 'AI handles defined workflows end-to-end; human in the loop on exceptions. Operations-grade autonomy.' },
  'autonomous': { front: 'Autonomous', back: 'AI runs without human review for individual steps. Human owns outcomes. Devin, Replit Agent, autonomous research.' },
  'copilot-pattern': { front: 'Copilot pattern', back: 'Suggestion-based; user remains the protagonist. GitHub Copilot, Microsoft Copilot. User does the steering.' },
  'autopilot-pattern': { front: 'Autopilot pattern', back: 'Autonomous execution with user review at boundaries. Replit Agent, Devin. AI does the steering with checkpoints.' },
  'generator-pattern': { front: 'Generator pattern (product)', back: 'The output is the product. Midjourney, Suno, Sora. Iterate to a satisfying artifact.' },
  'rewriter-pattern': { front: 'Rewriter pattern', back: 'Transform existing input. Grammarly rewrite, ChatGPT "improve this". Input + transformation = output.' },
  'summarizer-pattern': { front: 'Summarizer pattern', back: 'Compress long content. Meeting summaries, paper TL;DRs. Faithful compression is the success criterion.' },
  'classifier-pattern': { front: 'Classifier pattern', back: 'Categorize input into predefined buckets. Sentiment, intent, support routing. Often deterministic enough for Haiku-tier models.' },
  'extractor-pattern': { front: 'Extractor pattern', back: 'Structured data from unstructured input. Invoice fields, contract clauses. Pair with Pydantic / structured output.' },
  'conversational-interface-pattern': { front: 'Conversational interface pattern', back: 'Multi-turn dialogue as primary UX. ChatGPT, Claude.ai. Memory and context-management complexity.' },
  'embedded-suggest-pattern': { front: 'Embedded suggest pattern', back: 'Inline suggestions inside another tool. Grammarly in Gmail, Copilot in VSCode. Lowest-friction AI surfacing.' },
  'agent-pattern': { front: 'Agent pattern (product)', back: 'Multi-step autonomous task completion. Devin, Replit Agent, customer-support agents.' },
  'search-pattern': { front: 'Search pattern (AI product)', back: 'AI-augmented search over private corpora. Glean, Hebbia, AlphaSense. RAG productized.' },
  'q-a-pattern': { front: 'Q&A pattern', back: 'Question answering over documents. Legal Q&A, support docs. Trust hinges on faithful citations.' },
  'knowledge-worker-copilot': { front: 'Knowledge worker copilot', back: 'Productivity-suite-resident AI. M365 Copilot, Workspace Gemini. Embedded into existing workflows.' },
  'vertical-ai-assistant': { front: 'Vertical AI assistant', back: 'Domain-specific AI products. Harvey (legal), Abridge (clinical), Ambient AI. Deep workflow integration over horizontal generality.' },
  'ai-as-feature-vs-ai-as-product': { front: 'AI as feature vs AI as product', back: 'Is AI an enhancement to your existing product or the entire product? Different design, different defensibility.' },
  'the-trust-building-loop': { front: 'Trust-building loop', back: 'Cite sources, explain reasoning, allow correction. Standard pattern for AI products on serious workflows.' },
  'the-fallback-pattern': { front: 'Fallback pattern', back: 'How the product behaves when AI fails. Graceful degradation, human handoff. Determines crisis-day UX.' },
  'cost-shape-of-product': { front: 'Cost-shape-of-product', back: 'Per-seat vs per-token vs hybrid pricing. Determines what kind of usage is sustainable for your unit economics.' },
  'the-model-swap-architecture': { front: 'Model-swap architecture', back: 'Designing for model-agnostic interfaces so you can swap providers without rebuilding. Hedge against vendor lock-in.' },
  'latency-budgets-per-pattern': { front: 'Latency budgets per pattern', back: 'Conversational < 2s perceived; voice < 800ms; autocomplete < 100ms. Design choices flow from these caps.' },
  'streaming-as-ux': { front: 'Streaming as UX', back: 'Token-by-token streaming makes long generations feel fast. Canonical pattern; expected by users on chat-style products.' },
  'citation-and-source-visibility': { front: 'Citation and source visibility', back: 'RAG products must show where answers came from to build trust. Faithful citation > faithful answer alone.' },
  'edit-friendly-outputs': { front: 'Edit-friendly outputs', back: 'Outputs the user can refine (rich text, structured fields) outperform locked outputs. Editing is the trust-building act.' },
  'the-undo-regenerate-pattern': { front: 'Undo / regenerate pattern', back: 'Always provide a way to dismiss or rerun AI output. Trust foundation; lowers commitment-to-try barrier.' },

  // ===== Module 16: Data Engineering for AI =====
  'document-processing-pipeline': { front: 'Document processing pipeline', back: 'Ingest -> parse -> extract -> chunk -> embed -> index. The plumbing of every RAG system.' },
